function @@proc@@(p_text in varchar2) return date is
  l_d date;
begin
  -- a mask would be: to_date(p_text, 'yyyy-mm-dd')
  l_d := to_date(substr(p_text, 1, 10)); -- @expect
  dbms_output.put_line('parsed');
  return l_d;
end @@proc@@;

function @@proc@@(p_text in varchar2, p_flag in boolean) return timestamp is
  l_ts timestamp;
begin
  dbms_output.put_line('parsing');
  l_ts := case when p_flag then to_timestamp(p_text) else systimestamp end; -- @expect
  dbms_output.put_line('mask example: to_timestamp(x, fmt)');
  return l_ts;
end @@proc@@;

procedure @@proc@@(p_max in number) is
  l_cnt number := 0;
begin
  loop
    l_cnt := l_cnt + 1;
    @@proc2@@(l_cnt);
    exit when l_cnt = 'done'; -- @expect
    exit when l_cnt >= p_max;
  end loop;
end @@proc@@;

function @@proc@@(p_d in date) return varchar2 is
  l_r varchar2(10);
begin
  l_r := case
           when p_d > @@num@@ then 'late' -- @expect
           else 'ok'
         end;
  return l_r;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_code varchar2(10) := 'a';
  function known(p_x in number) return boolean is
  begin
    return p_x > 3;
  end known;
begin
  if known(p_id) then
    null;
  elsif l_code <> @@num@@ then -- @expect
    @@proc2@@(p_id);
  end if;
end @@proc@@;

