function @@proc@@(p_text in varchar2, p_fmt in varchar2) return date is
  l_d date;
  l_note varchar2(100) := 'use to_date(p_text) only with a mask';
begin
  -- l_d := to_date(p_text);  (old version, no mask)
  l_d := to_date(p_text, nvl(p_fmt, 'dd/mm/yyyy'));
  dbms_output.put_line(l_note);
  return l_d;
end @@proc@@;

procedure @@proc@@(p_qty in number, p_name in varchar2) is
  l_sql varchar2(200);
begin
  l_sql := 'qty = ''abc'' and name = 5';
  -- if p_qty = 'abc' then (never)
  if p_name = '@@str@@' then
    l_sql := l_sql || ' (named)';
  end if;
  if p_qty >= 8 then
    dbms_output.put_line(l_sql);
  end if;
end @@proc@@;

procedure @@proc@@(p_name in varchar2) is
  l_id "Order Line".id%type;
begin
  l_id := 5;
  if l_id = 'abc' then
    null;
  end if;
  if upper(p_name) = 6 then
    null;
  end if;
end @@proc@@;

function @@proc@@(p_a in number, p_b in varchar2, p_d in date) return boolean is
  l_ok boolean := false;
  l_n number := p_a;
  l_s varchar2(20) := p_b;
  l_d date := sysdate;
begin
  if l_ok = true then
    return true;
  end if;
  while l_n < p_a loop
    l_n := l_n + 1;
  end loop;
  return l_s <> p_b or p_d > l_d;
end @@proc@@;

procedure @@proc@@ is
  l_seen number := 0;
begin
  for r in (select id, @@col@@ as qty from @@tab@@) loop
    if r.qty = 'abc' then
      l_seen := l_seen + 1;
    elsif r.id = 'none' then
      l_seen := l_seen - 1;
    end if;
  end loop;
  dbms_output.put_line(l_seen);
end @@proc@@;
